#include "MemoryGame.h"
void startMemoryGame(){for(int i=0;i<MEMORY_MAX_LEVEL;i++)memorySequence[i]=random(0,4);memoryLevel=1;memoryShowPosition=0;memoryInputPosition=0;memoryChoice=0;memoryWon=false;memoryTimer=millis();state=STATE_MEMORY_SHOW;rgbPurple();clearEncoderEvents();}
void showMemorySymbol(uint8_t s){uint8_t f[8][12]={};switch(s){case 0:for(int y=1;y<4;y++)for(int x=1;x<5;x++)f[y][x]=1;break;case 1:for(int y=1;y<4;y++)for(int x=7;x<11;x++)f[y][x]=1;break;case 2:for(int y=5;y<8;y++)for(int x=1;x<5;x++)f[y][x]=1;break;case 3:for(int y=5;y<8;y++)for(int x=7;x<11;x++)f[y][x]=1;break;}showMatrix(f);}
void updateMemoryShow(){drawLCD("MEMORY","LEVEL "+String(memoryLevel));if(memoryShowPosition>=memoryLevel){memoryInputPosition=0;memoryChoice=0;state=STATE_MEMORY_INPUT;clearMatrix();return;}if(millis()-memoryTimer>=650){uint8_t s=memorySequence[memoryShowPosition];showMemorySymbol(s);tone(PIN_BUZZER,700+s*250,100);memoryShowPosition++;memoryTimer=millis();}}
void drawMemoryInput(){drawLCD("MEMORY","PICK "+String(memoryChoice+1)+" "+String(memoryInputPosition+1)+"/"+String(memoryLevel));showMemorySymbol(memoryChoice);}
void updateMemoryInput(){drawMemoryInput();int d=consumeEncoderDelta();if(d){memoryChoice+=d;while(memoryChoice<0)memoryChoice+=4;while(memoryChoice>=4)memoryChoice-=4;soundNavigate();}if(consumeEncoderPress()){uint8_t expected=memorySequence[memoryInputPosition];if(memoryChoice!=expected){memoryWon=false;state=STATE_MEMORY_RESULT;soundFailure();rgbRed();return;}soundSelect();memoryInputPosition++;if(memoryInputPosition>=memoryLevel){if(memoryLevel>=MEMORY_MAX_LEVEL){memoryWon=true;state=STATE_MEMORY_RESULT;soundSuccess();rgbGreen();return;}memoryLevel++;memoryShowPosition=0;memoryInputPosition=0;memoryChoice=0;memoryTimer=millis();state=STATE_MEMORY_SHOW;soundSuccess();}}}
void updateMemoryResult(){if(memoryWon){drawLCD("MEMORY MASTER","LEVEL "+String(memoryLevel));showEclipseLogo();rgbGreen();}else{drawLCD("MEMORY FAILED","LEVEL "+String(memoryLevel));rgbRed();}if(consumeEncoderPress())returnToGamesMenu();}
